                objectMapper.readTree(beforeRejected.getResponse().getContentAsString())
                        .get("code").asText());
        assertEquals("35", basins(violatedWindow).get("upperVolumeM3").asText());
        assertEquals(0, executions(a3).get("executions").size());
    }

